    cgLFLight( cgI.y, cgWP, cgN, cgDiff, cgSpC, cgSpD );
    cgLFLight( cgI.z, cgWP, cgN, cgDiff, cgSpC, cgSpD );
    cgLFLight( cgI.w, cgWP, cgN, cgDiff, cgSpC, cgSpD );
